// Verify HMAC signature + parse payload (webhook path)
// Cron path: load all brands with active competitors
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';

const isCron = !$input.first().json.body && !$input.first().json.headers;
if (isCron) {
  return [{ json: { brand_id: null, competitors: [], extraction_type: 'light', triggered_by: 'cron', is_cron: true } }];
}

const rawBody = $input.first().json.body ?? JSON.stringify($input.first().json);
const sig = $input.first().json.headers?.['x-n8n-signature'] ?? '';
const expected = crypto.createHmac('sha256', SECRET).update(rawBody).digest('hex');
if (sig !== expected) throw new Error('HMAC verification failed');

const payload = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
return [{ json: {
  brand_id: payload.brand_id,
  competitors: payload.competitors || [],
  extraction_type: payload.extraction_type || 'light',
  triggered_by: payload.triggered_by || 'A03',
  is_cron: false,
} }];

// Load all active competitor_accounts via the API route (same pattern as A03)
// For webhook calls: already have competitors[] in payload — build per-item list directly.
// For cron calls: we need to fetch all active competitors across all brands.
const parsed = $input.first().json;
if (!parsed.is_cron && parsed.competitors && parsed.competitors.length > 0) {
  // Webhook: use the competitors passed directly in the payload
  return parsed.competitors.map(c => ({ json: {
    competitor_id: c.competitor_id,
    brand_id: parsed.brand_id,
    handle_instagram: c.handle_instagram,
    extraction_type: parsed.extraction_type || 'light',
    triggered_by: parsed.triggered_by,
    is_cron: false,
  } }));
}
// Cron: signal that we need a full fetch — handled by next node
return [{ json: { ...parsed, needs_full_fetch: true } }];

// Sign request to /api/competitors/fetch-active
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const BASE = 'https://vagrancy-pupil-spiritism.ngrok-free.dev';
const body = JSON.stringify({ extraction_type: 'light', triggered_by: 'cron' });
const requestId = crypto.randomUUID();
const ts = new Date().toISOString();
const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');
return [{ json: {
  url: `${BASE}/api/competitors/fetch-active`,
  body,
  headers: {
    'content-type': 'application/json',
    'x-n8n-signature': sig,
    'x-n8n-request-id': requestId,
    'x-n8n-timestamp': ts,
  }
} }];

// Merge: cron result items come from fetch-active API, webhook items already split
// This node only runs after fetch-active (cron path). Pass items through.
const result = $input.first().json;
if (!result.ok || !Array.isArray(result.competitors)) return [{ json: { _no_competitors: true } }];
return result.competitors.map(c => ({ json: c }));

// Build Apify Instagram scraper input for this competitor
const c = $input.first().json;
const isDeep = c.extraction_type === 'deep';
return [{ json: {
  competitor_id: c.competitor_id,
  brand_id: c.brand_id,
  handle_instagram: c.handle_instagram,
  extraction_type: c.extraction_type || 'light',
  triggered_by: c.triggered_by,
  apify_body: {
    directUrls: [`https://www.instagram.com/${c.handle_instagram}/`],
    resultsType: 'posts',
    resultsLimit: isDeep ? 50 : 12,
    addParentData: true,
    scrapePostsUntilDate: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  }
} }];

// Merge Apify result with competitor metadata and sign the persist-snapshot call
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const BASE = 'https://vagrancy-pupil-spiritism.ngrok-free.dev';

const prep = $('Prepare Apify Inputs').first().json;
const apifyItems = $input.first().json;
const posts = Array.isArray(apifyItems) ? apifyItems : (apifyItems.items || []);

const bodyObj = {
  brand_id:         prep.brand_id,
  competitor_id:    prep.competitor_id,
  handle_instagram: prep.handle_instagram,
  extraction_type:  prep.extraction_type || 'light',
  triggered_by:     prep.triggered_by,
  apify_posts:      posts,
};
const body = JSON.stringify(bodyObj);
const requestId = crypto.randomUUID();
const ts = new Date().toISOString();
const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');

return [{ json: {
  url: `${BASE}/api/competitors/persist-snapshot`,
  body,
  headers: {
    'content-type': 'application/json',
    'x-n8n-signature': sig,
    'x-n8n-request-id': requestId,
    'x-n8n-timestamp': ts,
  },
  _meta: { brand_id: prep.brand_id, competitor_id: prep.competitor_id, handle_instagram: prep.handle_instagram, extraction_type: prep.extraction_type || 'light', posts_scraped: posts.length }
} }];

// Sign the log-cost API call
const crypto = require('crypto');
const SECRET = 'c56cb3e88c57ea77929fdbec379fb6ff1ab72fef61cee9084e9cb263892d8887';
const BASE = 'https://vagrancy-pupil-spiritism.ngrok-free.dev';

// Recover metadata from Sign node (two nodes back)
const signNode = $('Sign: persist-snapshot').first().json._meta || {};

const bodyObj = {
  brand_id:         signNode.brand_id,
  competitor_id:    signNode.competitor_id,
  handle_instagram: signNode.handle_instagram,
  extraction_type:  signNode.extraction_type || 'light',
  posts_scraped:    signNode.posts_scraped || 0,
  flow_id:          'N8N-A07',
};
const body = JSON.stringify(bodyObj);
const requestId = crypto.randomUUID();
const ts = new Date().toISOString();
const sig = crypto.createHmac('sha256', SECRET).update(body).digest('hex');

return [{ json: {
  url: `${BASE}/api/competitors/log-cost`,
  body,
  headers: {
    'content-type': 'application/json',
    'x-n8n-signature': sig,
    'x-n8n-request-id': requestId,
    'x-n8n-timestamp': ts,
  }
} }];

// Apify call failed — log and pass through so the flow doesn't hang
console.error('[A07] Apify scrape failed for', $('Prepare Apify Inputs').first().json.handle_instagram);
return [{ json: { _apify_failed: true } }];
